INSERT INTO `es_events` VALUES ('46caee26-eb44-4d90-8583-06f961abe387','CSIT Interview 2026','Final Rating is auto-computed from AVE/GPA, NOAT, and Interview using admin-configured max scores. Strand alignment bonus is applied to Interview points only.',NULL,'standard','[{\"score\":4,\"label\":\"Excellent\"},{\"score\":3,\"label\":\"Exceeds Expectations\"},{\"score\":2,\"label\":\"Meets Expectations\"},{\"score\":1,\"label\":\"Meets Expectations Sometimes\"},{\"score\":0,\"label\":\"Does Not Meet Expectations\"}]',0,'{\"maxScores\":{\"aveGpa\":100,\"noat\":100,\"interview\":100},\"scoreWeights\":{\"aveGpa\":40,\"noat\":40,\"interview\":20},\"strandBonus\":{\"singleAlignedBonusPoints\":10,\"multiAlignedBonusPoints\":10,\"singleAlignedStrands\":[],\"multiAlignedStrands\":[\"Computer Programming (ICT)\",\"Computer Systems Servicing (ICT)\"]}}','2026-05-28 00:57:47.674');
